insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-listening-10', 'listening', null, null, '/audio/listening/q-listening-10.mp3', 'Man: I''m thinking about switching my major from biology to chemistry.
Woman: That''s a big decision. Have you spoken with your academic advisor yet?
Man: Not yet, I wanted your opinion first since you switched majors too.
Woman: My honest advice is to meet the advisor before deciding — they can tell you exactly which credits will transfer.', 'What is the man considering doing?', '[{"id":"a","text":"Dropping out of university"},{"id":"b","text":"Switching his major from biology to chemistry"},{"id":"c","text":"Switching his major from chemistry to biology"},{"id":"d","text":"Becoming an academic advisor"}]'::jsonb, 'b', 'He says, "I''m thinking about switching my major from biology to chemistry."', 'easy', array['listening-comprehension']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
