insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-listening-57', 'listening', null, null, '/audio/listening/q-listening-57.mp3', 'Man: The forecast says heavy rain all afternoon, so the picnic is cancelled.
Woman: Oh no, the kids were really looking forward to it.
Man: The museum is open late tonight and has a special children''s science show at four.
Woman: That sounds perfect. Should I book tickets now?
Man: Yes, and I''ll check if the parking is still free after six.
Woman: Great, let''s meet at the museum entrance at three thirty.', 'Why was the picnic cancelled?', '[{"id":"a","text":"The park is closed for maintenance."},{"id":"b","text":"Heavy rain is forecast for the afternoon."},{"id":"c","text":"The children got sick."},{"id":"d","text":"The tickets were sold out."}]'::jsonb, 'b', 'The man says "the forecast says heavy rain all afternoon, so the picnic is cancelled."', 'easy', array['listening-comprehension']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
