insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-listening-60', 'listening', null, null, '/audio/listening/q-listening-60.mp3', 'Woman: I ordered a laptop stand three days ago and it was supposed to arrive yesterday, but nothing came.
Man: I''m sorry about that. Let me check the tracking... It shows the package was delayed at the sorting center.
Woman: Can you send it today?
Man: The earliest delivery slot is tomorrow between nine and noon. I''ll mark it as urgent so it''s the first drop.
Woman: Okay, and please send me a confirmation message when it''s out for delivery.', 'Why hasn''t the woman received her order?', '[{"id":"a","text":"The item is out of stock."},{"id":"b","text":"The package was delayed at the sorting center."},{"id":"c","text":"The delivery address was wrong."},{"id":"d","text":"She never placed the order."}]'::jsonb, 'b', 'The man checks the tracking and reports "the package was delayed at the sorting center."', 'easy', array['listening-comprehension']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-listening-61', 'listening', null, null, '/audio/listening/q-listening-60.mp3', 'Woman: I ordered a laptop stand three days ago and it was supposed to arrive yesterday, but nothing came.
Man: I''m sorry about that. Let me check the tracking... It shows the package was delayed at the sorting center.
Woman: Can you send it today?
Man: The earliest delivery slot is tomorrow between nine and noon. I''ll mark it as urgent so it''s the first drop.
Woman: Okay, and please send me a confirmation message when it''s out for delivery.', 'What does the man offer to do about the delivery?', '[{"id":"a","text":"Cancel the order and refund the payment"},{"id":"b","text":"Mark it as urgent so it is the first delivery tomorrow"},{"id":"c","text":"Deliver it personally today"},{"id":"d","text":"Ship a replacement from another warehouse"}]'::jsonb, 'b', 'He says "I''ll mark it as urgent so it''s the first drop" for tomorrow''s delivery slot.', 'medium', array['listening-comprehension']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-listening-62', 'listening', null, null, '/audio/listening/q-listening-60.mp3', 'Woman: I ordered a laptop stand three days ago and it was supposed to arrive yesterday, but nothing came.
Man: I''m sorry about that. Let me check the tracking... It shows the package was delayed at the sorting center.
Woman: Can you send it today?
Man: The earliest delivery slot is tomorrow between nine and noon. I''ll mark it as urgent so it''s the first drop.
Woman: Okay, and please send me a confirmation message when it''s out for delivery.', 'What does the woman ask to receive before the delivery?', '[{"id":"a","text":"A refund receipt"},{"id":"b","text":"A confirmation message when the package is out for delivery"},{"id":"c","text":"The tracking number by post"},{"id":"d","text":"A phone call from the driver"}]'::jsonb, 'b', 'She asks, "please send me a confirmation message when it''s out for delivery."', 'easy', array['listening-comprehension']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-1', 'writingAnalysis', null, null, null, null, 'Identify the error: "Each of the employees are required to submit their timesheet by Friday."', '[{"id":"a","text":"\"Each of\" should be \"All of\""},{"id":"b","text":"\"are\" should be \"is\""},{"id":"c","text":"\"their\" should be \"his\""},{"id":"d","text":"\"submit\" should be \"submitting\""}]'::jsonb, 'b', '"Each of the employees" is singular, so the verb should be "is", not "are".', 'medium', array['error-identification','subject-verb-agreement']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-2', 'writingAnalysis', null, null, null, null, 'Identify the error: "She has less problems than I expected with the new software."', '[{"id":"a","text":"\"less\" should be \"fewer\""},{"id":"b","text":"\"has\" should be \"have\""},{"id":"c","text":"\"expected\" should be \"expecting\""},{"id":"d","text":"No error"}]'::jsonb, 'a', '"Problems" is countable, so "fewer" is correct; "less" is for uncountable nouns.', 'medium', array['error-identification','countable-uncountable']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-3', 'writingAnalysis', null, null, null, null, 'Identify the error: "The manager, along with two supervisors, were present at the safety inspection."', '[{"id":"a","text":"\"along with\" should be \"and\""},{"id":"b","text":"\"were\" should be \"was\""},{"id":"c","text":"\"present\" should be \"presence\""},{"id":"d","text":"\"the\" should be removed"}]'::jsonb, 'b', '"Along with..." doesn''t change the subject''s number; the subject is "the manager" (singular), so "was" is correct.', 'hard', array['error-identification','subject-verb-agreement']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-4', 'writingAnalysis', null, null, null, null, 'Identify the error: "Having finished the project early, the deadline was no longer a concern for the team."', '[{"id":"a","text":"\"Having finished\" is a dangling modifier — it doesn''t logically refer to \"the deadline\""},{"id":"b","text":"\"no longer\" should be \"no more\""},{"id":"c","text":"\"for the team\" should be removed"},{"id":"d","text":"No error"}]'::jsonb, 'a', 'The introductory phrase should modify "the team" (who finished the project), not "the deadline" — a classic dangling modifier.', 'hard', array['error-identification','dangling-modifiers']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-5', 'writingAnalysis', null, null, null, null, 'Identify the error: "The manager asked us to arriving early, prepare the materials, and to greet guests."', '[{"id":"a","text":"\"to arriving\" should be \"to arrive\", to match the parallel infinitive structure"},{"id":"b","text":"\"prepare\" should be \"preparing\""},{"id":"c","text":"\"to greet\" should be \"greeting\""},{"id":"d","text":"No error"}]'::jsonb, 'a', 'A list of parallel actions should share the same grammatical form — "to arrive, prepare, and greet" (infinitives without "to" after the first).', 'medium', array['error-identification','parallel-structure']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-6', 'writingAnalysis', null, null, null, null, 'Identify the error: "By next year, she will have working here for two decades."', '[{"id":"a","text":"\"will have working\" should be \"will have been working\""},{"id":"b","text":"\"By next year\" should be \"Until next year\""},{"id":"c","text":"\"two decades\" should be \"two decade\""},{"id":"d","text":"No error"}]'::jsonb, 'a', 'The future perfect continuous requires "will have been" + present participle, not "will have" + present participle.', 'hard', array['error-identification','tenses']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-7', 'writingAnalysis', null, null, null, null, 'Identify the error: "Between you and I, the proposal needs major revisions."', '[{"id":"a","text":"\"I\" should be \"me\""},{"id":"b","text":"\"Between\" should be \"Among\""},{"id":"c","text":"\"needs\" should be \"need\""},{"id":"d","text":"No error"}]'::jsonb, 'a', 'As the object of the preposition "between," the correct pronoun is the object form "me," not the subject form "I."', 'medium', array['error-identification','pronoun-case']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-8', 'writingAnalysis', null, null, null, null, 'Identify the error: "Neither the manager nor the employees was informed about the schedule change."', '[{"id":"a","text":"\"was\" should be \"were\""},{"id":"b","text":"\"Neither\" should be \"Either\""},{"id":"c","text":"\"informed\" should be \"inform\""},{"id":"d","text":"No error"}]'::jsonb, 'a', 'With "neither...nor," the verb agrees with the nearer subject — "employees" (plural) — so "were" is correct.', 'hard', array['error-identification','subject-verb-agreement','correlative-conjunctions']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-9', 'writingAnalysis', null, null, null, null, 'Identify the error: "We don''t have no more time to waste on this project."', '[{"id":"a","text":"\"don''t have no\" should be \"don''t have any\""},{"id":"b","text":"\"waste\" should be \"wasting\""},{"id":"c","text":"\"time\" should be \"times\""},{"id":"d","text":"No error"}]'::jsonb, 'a', '"Don''t have no" is a double negative; standard English uses "don''t have any".', 'easy', array['error-identification','double-negative']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-10', 'writingAnalysis', null, null, null, null, 'Identify the error: "The companys'' profits increased significantly last quarter."', '[{"id":"a","text":"\"companys''\" should be \"company''s\""},{"id":"b","text":"\"profits\" should be \"profit\""},{"id":"c","text":"\"increased\" should be \"increasing\""},{"id":"d","text":"No error"}]'::jsonb, 'a', 'A singular possessive noun takes ''s, not s'': "company''s", not "companys''".', 'medium', array['error-identification','possessives']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-11', 'writingAnalysis', null, null, null, null, 'Identify the error: "The proposal was rejected, the board felt it lacked sufficient detail."', '[{"id":"a","text":"The comma should be replaced with \"because\""},{"id":"b","text":"\"rejected\" should be \"rejecting\""},{"id":"c","text":"\"board\" should be \"boards\""},{"id":"d","text":"No error"}]'::jsonb, 'a', 'Joining two independent clauses with only a comma creates a comma splice; a conjunction like "because" is needed.', 'hard', array['error-identification','comma-splice']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-12', 'writingAnalysis', null, null, null, null, 'Identify the error: "The new policy will make employees to work fewer hours."', '[{"id":"a","text":"\"to work\" should be \"work\""},{"id":"b","text":"\"will make\" should be \"made\""},{"id":"c","text":"\"fewer\" should be \"less\""},{"id":"d","text":"No error"}]'::jsonb, 'a', '"Make + object" is followed by a bare infinitive, not "to" + verb: "make employees work".', 'medium', array['error-identification','causative']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-13', 'writingAnalysis', null, null, null, null, 'Identify the error: "I am looking forward to hear from you soon."', '[{"id":"a","text":"\"to hear\" should be \"to hearing\""},{"id":"b","text":"\"am looking\" should be \"look\""},{"id":"c","text":"\"soon\" should be \"early\""},{"id":"d","text":"No error"}]'::jsonb, 'a', '"Look forward to" takes a gerund ("to hearing"), because "to" here is a preposition, not part of an infinitive.', 'easy', array['error-identification','gerunds-infinitives']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-14', 'writingAnalysis', null, null, null, null, 'Identify the error: "The equipment in the computer labs are outdated."', '[{"id":"a","text":"\"are\" should be \"is\""},{"id":"b","text":"\"equipment\" should be \"equipments\""},{"id":"c","text":"\"outdated\" should be \"out of date\""},{"id":"d","text":"No error"}]'::jsonb, 'a', '"Equipment" is an uncountable noun that takes a singular verb, so "the equipment...is outdated".', 'medium', array['error-identification','subject-verb-agreement','countable-uncountable']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-15', 'writingAnalysis', null, null, null, null, 'Identify the error: "Hardly had he arrived at the station when the train had left."', '[{"id":"a","text":"\"had he arrived\" should be \"he had arrived\""},{"id":"b","text":"\"when\" should be \"than\""},{"id":"c","text":"\"had left\" should be \"left\""},{"id":"d","text":"No error"}]'::jsonb, 'c', 'In the "hardly...when" structure the second clause takes the simple past ("the train left"), not the past perfect.', 'hard', array['error-identification','inversion','tenses']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-16', 'writingAnalysis', null, null, null, null, 'Identify the error: "The new employees must complete the training before they will start working."', '[{"id":"a","text":"\"will start\" should be \"start\""},{"id":"b","text":"\"must complete\" should be \"must have completed\""},{"id":"c","text":"\"working\" should be \"work\""},{"id":"d","text":"No error"}]'::jsonb, 'a', 'Time clauses introduced by "before", "when", or "after" use the present simple for future meaning: "before they start working".', 'medium', array['error-identification','tenses','time-clauses']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-17', 'writingAnalysis', null, null, null, null, 'Identify the error: "Despite of the warning, many students ignored the announcement."', '[{"id":"a","text":"\"Despite of\" should be \"Despite\""},{"id":"b","text":"\"ignored\" should be \"ignore\""},{"id":"c","text":"\"the warning\" should be \"warnings\""},{"id":"d","text":"No error"}]'::jsonb, 'a', '"Despite" is used alone (or as "in spite of"), never "despite of".', 'easy', array['error-identification','prepositions']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-18', 'writingAnalysis', null, null, null, null, 'Identify the error: "If he had studied harder, he would pass the exam."', '[{"id":"a","text":"\"had studied\" should be \"studied\""},{"id":"b","text":"\"would pass\" should be \"would have passed\""},{"id":"c","text":"\"harder\" should be \"hard\""},{"id":"d","text":"No error"}]'::jsonb, 'b', 'This is a third conditional (past unreal situation): "If + past perfect, would have + past participle" — "would have passed".', 'hard', array['error-identification','conditionals']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-19', 'writingAnalysis', null, null, null, null, 'Identify the error: "The committee has reached its decision, the results will be announced tomorrow."', '[{"id":"a","text":"A comma splice joins two independent clauses without a conjunction."},{"id":"b","text":"\"has\" should be \"have\""},{"id":"c","text":"\"its\" should be \"it''s\""},{"id":"d","text":"No error"}]'::jsonb, 'a', '"The committee has reached its decision" and "the results will be announced" are both independent clauses; joining them with only a comma creates a comma splice.', 'medium', array['error-identification','comma-splice']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-20', 'writingAnalysis', null, null, null, null, 'Identify the error: "The new policy will effect the way employees report their expenses."', '[{"id":"a","text":"\"effect\" should be \"affect\""},{"id":"b","text":"\"report\" should be \"reports\""},{"id":"c","text":"\"their\" should be \"there\""},{"id":"d","text":"No error"}]'::jsonb, 'a', '"Affect" is the verb (to influence); "effect" is a noun (result). The sentence needs the verb "affect".', 'easy', array['error-identification','commonly-confused-words']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-21', 'writingAnalysis', null, null, null, null, 'Identify the error: "Each student must bring their own laptop to the exam."', '[{"id":"a","text":"\"their\" should be \"his or her\" in formal usage when the subject is singular"},{"id":"b","text":"\"must\" should be \"can\""},{"id":"c","text":"\"bring\" should be \"brought\""},{"id":"d","text":"No error"}]'::jsonb, 'a', '"Each student" is singular, so in formal writing the possessive should agree: "his or her own laptop" (or the sentence should use a plural subject).', 'medium', array['error-identification','pronoun-agreement']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-22', 'writingAnalysis', null, null, null, null, 'Identify the error: "Walking down the street, the building caught my attention."', '[{"id":"a","text":"\"Walking down the street\" is a dangling modifier — it describes a person, not \"the building\""},{"id":"b","text":"\"caught\" should be \"catches\""},{"id":"c","text":"\"my\" should be \"mine\""},{"id":"d","text":"No error"}]'::jsonb, 'a', 'The introductory phrase should modify the person who is walking; "the building" can''t walk, so the modifier dangles.', 'hard', array['error-identification','dangling-modifiers']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-23', 'writingAnalysis', null, null, null, null, 'Identify the error: "She wanted to buy a new car, get a better job, and to move to a bigger apartment."', '[{"id":"a","text":"\"to move\" breaks the parallel structure — it should be \"move\""},{"id":"b","text":"\"buy\" should be \"bought\""},{"id":"c","text":"\"better\" should be \"more good\""},{"id":"d","text":"No error"}]'::jsonb, 'a', 'Items in a list must be parallel: "to buy, get, and move" — the "to" before "move" breaks the pattern.', 'medium', array['error-identification','parallel-structure']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-24', 'writingAnalysis', null, null, null, null, 'Identify the error: "The team are proud of its achievement this season."', '[{"id":"a","text":"\"are\" should be \"is\" to match the singular subject \"team\" and \"its\""},{"id":"b","text":"\"proud\" should be \"pride\""},{"id":"c","text":"\"its\" should be \"it''s\""},{"id":"d","text":"No error"}]'::jsonb, 'a', '"Team" is treated as a singular collective noun here (matching "its"), so the verb should be "is", not "are".', 'medium', array['error-identification','subject-verb-agreement']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-25', 'writingAnalysis', null, null, null, null, 'Identify the error: "Everyone who attended the conference received their certificate."', '[{"id":"a","text":"\"Everyone\" is singular, so \"their\" is a pronoun agreement error in formal writing"},{"id":"b","text":"\"attended\" should be \"had attended\""},{"id":"c","text":"\"received\" should be \"receive\""},{"id":"d","text":"No error"}]'::jsonb, 'a', '"Everyone" takes a singular verb and singular pronoun agreement in formal usage: "his or her certificate".', 'medium', array['error-identification','pronoun-agreement']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-26', 'writingAnalysis', null, null, null, null, 'Identify the error: "The amount of students who failed the exam increased this year."', '[{"id":"a","text":"\"amount\" should be \"number\" — students are countable"},{"id":"b","text":"\"failed\" should be \"fail\""},{"id":"c","text":"\"increased\" should be \"increasing\""},{"id":"d","text":"No error"}]'::jsonb, 'a', '"Amount" is used with uncountable nouns; countable items like "students" take "number".', 'easy', array['error-identification','countable-uncountable']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-27', 'writingAnalysis', null, null, null, null, 'Identify the error: "Had he arrived earlier, he would have met the director."', '[{"id":"a","text":"No error"},{"id":"b","text":"\"Had he arrived\" should be \"If he has arrived\""},{"id":"c","text":"\"would have met\" should be \"would meet\""},{"id":"d","text":"\"earlier\" should be \"more early\""}]'::jsonb, 'a', '"Had + subject + past participle" is a correct inverted third conditional: "Had he arrived earlier, he would have met...".', 'hard', array['error-identification','conditionals','inversion']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-28', 'writingAnalysis', null, null, null, null, 'Identify the error: "The manager, as well as the employees, were asked to attend the safety meeting."', '[{"id":"a","text":"\"were\" should be \"was\" — \"as well as\" doesn''t make the subject plural"},{"id":"b","text":"\"asked\" should be \"asking\""},{"id":"c","text":"\"attend\" should be \"attending\""},{"id":"d","text":"No error"}]'::jsonb, 'a', 'The subject is "the manager" (singular); "as well as the employees" is an added phrase, so the verb stays "was".', 'hard', array['error-identification','subject-verb-agreement']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-29', 'writingAnalysis', null, null, null, null, 'Identify the error: "He is one of the students who has completed the advanced course."', '[{"id":"a","text":"\"has\" should be \"have\" — the antecedent of \"who\" is \"students\" (plural)"},{"id":"b","text":"\"completed\" should be \"completing\""},{"id":"c","text":"\"advanced\" should be \"advancing\""},{"id":"d","text":"No error"}]'::jsonb, 'a', 'The relative pronoun "who" refers to "students" (plural), so the verb must be "have completed".', 'hard', array['error-identification','subject-verb-agreement','relative-clauses']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-30', 'writingAnalysis', null, null, null, null, 'Identify the error: "She was supposed to be home by now, but her flight was delay."', '[{"id":"a","text":"\"delay\" should be \"delayed\""},{"id":"b","text":"\"supposed\" should be \"supposing\""},{"id":"c","text":"\"by now\" should be \"until now\""},{"id":"d","text":"No error"}]'::jsonb, 'a', 'After "was", a past participle is needed: "was delayed".', 'easy', array['error-identification','tenses']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-31', 'writingAnalysis', null, null, null, null, 'Identify the error: "If he would have checked the map, he wouldn''t have gotten lost."', '[{"id":"a","text":"\"would have checked\" should be \"had checked\""},{"id":"b","text":"\"gotten\" should be \"get\""},{"id":"c","text":"\"the map\" should be \"a map\""},{"id":"d","text":"No error"}]'::jsonb, 'a', 'The if-clause of a third conditional uses past perfect: "If he had checked", not "would have checked".', 'hard', array['error-identification','conditionals']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-32', 'writingAnalysis', null, null, null, null, 'Identify the error: "The report include a detailed analysis of the market trends."', '[{"id":"a","text":"\"include\" should be \"includes\" — \"report\" is singular"},{"id":"b","text":"\"analysis\" should be \"analyses\""},{"id":"c","text":"\"trends\" should be \"trend\""},{"id":"d","text":"No error"}]'::jsonb, 'a', 'The singular subject "report" requires the third-person singular verb "includes".', 'easy', array['error-identification','subject-verb-agreement']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-33', 'writingAnalysis', null, null, null, null, 'Identify the error: "Neither of the two proposals seem practical enough to fund."', '[{"id":"a","text":"\"Neither of\" should be \"Either of\""},{"id":"b","text":"\"seem\" should be \"seems\""},{"id":"c","text":"\"practical\" should be \"practically\""},{"id":"d","text":"No error"}]'::jsonb, 'b', '"Neither of" is treated as singular, so the verb must be "seems", not "seem".', 'medium', array['error-identification','subject-verb-agreement']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-34', 'writingAnalysis', null, null, null, null, 'Identify the error: "The lecture was both informative and it was also entertaining."', '[{"id":"a","text":"\"both\" should be \"either\""},{"id":"b","text":"\"it was also\" should be \"entertaining\" (parallel structure)"},{"id":"c","text":"\"lecture\" should be \"lecturer\""},{"id":"d","text":"No error"}]'::jsonb, 'b', '"Both...and" requires parallel forms: "informative and entertaining" without the repeated "it was also".', 'medium', array['error-identification','parallelism']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-35', 'writingAnalysis', null, null, null, null, 'Identify the error: "Having finished the assignment, the library was a good place to relax."', '[{"id":"a","text":"\"Having finished\" should be \"Finishing\""},{"id":"b","text":"\"the library\" should be \"we found the library\" (the opening phrase needs a logical subject)"},{"id":"c","text":"\"relax\" should be \"relaxing\""},{"id":"d","text":"No error"}]'::jsonb, 'b', 'The dangling modifier "Having finished the assignment" needs a subject that can finish an assignment — "we" — not "the library".', 'hard', array['error-identification','dangling-modifier']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-36', 'writingAnalysis', null, null, null, null, 'Identify the error: "Every student must submit their homework before noon."', '[{"id":"a","text":"\"Every\" should be \"All\""},{"id":"b","text":"\"their\" should be \"his or her\" (singular antecedent)"},{"id":"c","text":"\"submit\" should be \"submits\""},{"id":"d","text":"No error"}]'::jsonb, 'b', '"Every student" is singular, so the pronoun must be singular: "his or her homework".', 'medium', array['error-identification','pronoun-agreement']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-37', 'writingAnalysis', null, null, null, null, 'Identify the error: "The amount of volunteers who signed up was far higher than expected."', '[{"id":"a","text":"\"amount\" should be \"number\" — \"volunteers\" is countable"},{"id":"b","text":"\"who\" should be \"which\""},{"id":"c","text":"\"higher\" should be \"more high\""},{"id":"d","text":"No error"}]'::jsonb, 'a', '"Volunteers" is a countable noun, so it takes "number of", not "amount of".', 'easy', array['error-identification','countable-uncountable']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-38', 'writingAnalysis', null, null, null, null, 'Identify the error: "Despite of the heavy rain, the match continued without interruption."', '[{"id":"a","text":"\"Despite of\" should be \"Despite\" or \"In spite of\""},{"id":"b","text":"\"continued\" should be \"continues\""},{"id":"c","text":"\"interruption\" should be \"interrupting\""},{"id":"d","text":"No error"}]'::jsonb, 'a', '"Despite" is used without "of"; the correct alternatives are "Despite the heavy rain" or "In spite of the heavy rain".', 'easy', array['error-identification','prepositions']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-reading-43', 'reading', null, 'passage-dna-genetics', null, null, 'In the passage, the word ''traits'' is closest in meaning to', '[{"id":"a","text":"flaws"},{"id":"b","text":"characteristics"},{"id":"c","text":"illnesses"},{"id":"d","text":"prices"}]'::jsonb, 'b', 'The passage uses ''traits such as eye color and height'' to describe distinguishing characteristics of an organism.', 'easy', array['reading-comprehension','vocabulary']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
