insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-reading-77', 'reading', null, 'passage-indoor-air-pollution', null, null, 'According to the passage, why can pollutant levels become high inside well-sealed buildings?', '[{"id":"a","text":"Because modern buildings are designed to keep air trapped inside"},{"id":"b","text":"Because windows are always left open"},{"id":"c","text":"Because outdoor air is always cleaner"},{"id":"d","text":"Because factories release most indoor pollution"}]'::jsonb, 'a', 'The passage says that because modern buildings are well sealed to save energy, ''polluted air tends to remain trapped inside.''', 'easy', array['reading-comprehension']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
