insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-reading-80', 'reading', null, 'passage-muhammad-ali', null, null, 'According to the passage, what happened after Ali refused to serve in the military?', '[{"id":"a","text":"He won another Olympic gold medal"},{"id":"b","text":"His boxing license was suspended and he lost several years at the peak of his career"},{"id":"c","text":"He retired from public life immediately"},{"id":"d","text":"He moved back to Louisville permanently"}]'::jsonb, 'b', 'The passage states his refusal led to his boxing license being suspended and cost him several years at the peak of his career.', 'medium', array['reading-comprehension']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
