insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-reading-86', 'reading', null, 'passage-sugar-health-risks', null, null, 'According to the passage, why are sugary drinks a particular concern?', '[{"id":"a","text":"They are consumed quickly without making people feel full"},{"id":"b","text":"They contain no calories at all"},{"id":"c","text":"They are sold only to children"},{"id":"d","text":"They strengthen tooth enamel"}]'::jsonb, 'a', 'The passage says sugary drinks are a particular concern because they are ''consumed quickly without making people feel full.''', 'medium', array['reading-comprehension']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-reading-87', 'reading', null, 'passage-sugar-health-risks', null, null, 'What is the passage mainly about?', '[{"id":"a","text":"The history of sugar production"},{"id":"b","text":"The health problems associated with a high-sugar diet and advice to limit it"},{"id":"c","text":"The difference between glucose and fat"},{"id":"d","text":"How to make breakfast cereals healthier"}]'::jsonb, 'b', 'The passage explains how sugar affects the body and the diseases linked to it, then recommends limiting added sugars.', 'medium', array['reading-comprehension','main-idea']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-listening-63', 'listening', null, null, '/audio/listening/q-listening-63.mp3', 'Receptionist: Hello, English Testing Center, how can I help you?
Student: Hello, I''d like to book a seat for the English placement test on Saturday.
Receptionist: Certainly. We have two sessions, one at nine in the morning and another at two in the afternoon. Which do you prefer?
Student: The morning session, please, because I have a training course in the afternoon. Is that the one that costs two hundred riyals?
Receptionist: Actually, both sessions cost two hundred riyals, and you only pay a fifty riyal deposit today. So, Saturday at nine it is.
Student: Perfect, that works for me. Please confirm the booking.', 'How much does the English placement test cost?', '[{"id":"a","text":"Fifty riyals"},{"id":"b","text":"Two hundred riyals"},{"id":"c","text":"Two hundred and fifty riyals"},{"id":"d","text":"Twenty riyals"}]'::jsonb, 'b', 'The receptionist says, "both sessions cost two hundred riyals," and only the deposit is fifty riyals.', 'easy', array['listening-comprehension']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-listening-64', 'listening', null, null, '/audio/listening/q-listening-63.mp3', 'Receptionist: Hello, English Testing Center, how can I help you?
Student: Hello, I''d like to book a seat for the English placement test on Saturday.
Receptionist: Certainly. We have two sessions, one at nine in the morning and another at two in the afternoon. Which do you prefer?
Student: The morning session, please, because I have a training course in the afternoon. Is that the one that costs two hundred riyals?
Receptionist: Actually, both sessions cost two hundred riyals, and you only pay a fifty riyal deposit today. So, Saturday at nine it is.
Student: Perfect, that works for me. Please confirm the booking.', 'Why does the student choose the morning session?', '[{"id":"a","text":"Because the afternoon session is full"},{"id":"b","text":"Because the morning session is cheaper"},{"id":"c","text":"Because he has a training course in the afternoon"},{"id":"d","text":"Because the center closes at noon"}]'::jsonb, 'c', 'The student says he prefers the morning session "because I have a training course in the afternoon."', 'medium', array['listening-comprehension']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-listening-65', 'listening', null, null, '/audio/listening/q-listening-63.mp3', 'Receptionist: Hello, English Testing Center, how can I help you?
Student: Hello, I''d like to book a seat for the English placement test on Saturday.
Receptionist: Certainly. We have two sessions, one at nine in the morning and another at two in the afternoon. Which do you prefer?
Student: The morning session, please, because I have a training course in the afternoon. Is that the one that costs two hundred riyals?
Receptionist: Actually, both sessions cost two hundred riyals, and you only pay a fifty riyal deposit today. So, Saturday at nine it is.
Student: Perfect, that works for me. Please confirm the booking.', 'What is the student''s final decision about the test?', '[{"id":"a","text":"He will book the afternoon session"},{"id":"b","text":"He will take the test at nine o''clock on Saturday"},{"id":"c","text":"He will cancel the booking"},{"id":"d","text":"He will pay the full fee today"}]'::jsonb, 'b', 'After learning both sessions cost the same, the student keeps the morning booking, and the receptionist confirms "Saturday at nine it is."', 'medium', array['listening-inference']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-listening-66', 'listening', null, null, '/audio/listening/q-listening-66.mp3', 'Woman: You always seem tired after lunch. What do you usually eat?
Man: I grab a burger and fries with a large soft drink almost every day.
Woman: That''s a lot of sugar and fat. Maybe you should try grilled chicken with salad instead.
Man: But I love fast food. Doesn''t the protein in a burger help?
Woman: Some, but the extra sugar and salt outweigh the benefit. Try to add one salad a week and drink more water.
Man: Okay, I''ll start with the salad every Thursday and see how I feel.', 'What does the man eat for lunch almost every day?', '[{"id":"a","text":"Grilled chicken with salad"},{"id":"b","text":"A burger and fries with a large soft drink"},{"id":"c","text":"Fish with vegetables"},{"id":"d","text":"A salad with water"}]'::jsonb, 'b', 'The man says he grabs "a burger and fries with a large soft drink almost every day."', 'easy', array['listening-comprehension']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
