insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-listening-84', 'listening', null, null, '/audio/listening/q-listening-84.mp3', 'Man: Do you still buy newspapers? Everyone I know reads the news on their phones now.
Woman: I do subscribe to one printed paper, but I mostly read digital news on my tablet.
Man: Is there any real advantage to the digital version?
Woman: Yes, it is updated all day, I can search old articles in seconds, and it only costs twenty-five riyals a month.
Man: So why keep the printed subscription at all?
Woman: Because my father prefers paper, even though it costs forty riyals a month. I keep it mainly for him.', 'How much does the woman pay for the printed newspaper each month?', '[{"id":"a","text":"Twenty-five riyals"},{"id":"b","text":"Forty riyals"},{"id":"c","text":"Fifteen riyals"},{"id":"d","text":"Fifty riyals"}]'::jsonb, 'b', 'The woman says the printed paper "costs forty riyals a month."', 'easy', array['listening-comprehension']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
