insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm-reading-18', 'reading', null, 'passage-sm-5', null, null, 'What did the ancient Egyptians do with the stems of the papyrus plant?', '[{"id":"a","text":"They boiled them to make ink."},{"id":"b","text":"They flattened them and pressed them together."},{"id":"c","text":"They planted them in long rows."},{"id":"d","text":"They burned them for fuel."}]'::jsonb, 'b', 'The passage describes how the Egyptians flattened the fibrous stems, laid them crosswise, and pressed them together so they stuck and could be written on.', 'easy', array['reading-comprehension','detail','step-mock']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
