insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm-reading-20', 'reading', null, 'passage-sm-5', null, null, 'According to the passage, how did the art of paper-making reach Europe?', '[{"id":"a","text":"Chinese traders sold it directly to European kings."},{"id":"b","text":"Arab merchants learned the secret and took it to Spain."},{"id":"c","text":"European scientists invented it on their own."},{"id":"d","text":"The ancient Egyptians brought it by sea."}]'::jsonb, 'b', 'Chinese traders carried the knowledge to Samarkand, where Arab merchants learned it and later brought it to Spain, from which it spread across Europe.', 'medium', array['reading-comprehension','detail','step-mock']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
