insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm-listening-7', 'listening', null, null, null, 'Customer: Good morning. I''d like a train ticket from Sydney to Melbourne, please.
Ticket Seller: Good morning, sir. Which day would you like to travel?
Customer: Tuesday, the 18th of November.
Ticket Seller: Would you like a one-way ticket or a round-trip ticket?
Customer: A round-trip ticket, please.
Ticket Seller: I''m sorry, sir, but there are no round-trip tickets left for Tuesday.
Customer: Hmm. What about Wednesday, then?
Ticket Seller: Let me check... Yes, we do have round-trip tickets available on Wednesday.
Customer: Perfect. Please book me a seat for Wednesday.
Ticket Seller: Certainly. That will be $120 in total.
Customer: Here you are. Thank you.
Ticket Seller: Here are your ticket and receipt. The train departs at 6:15 in the morning, so please arrive at the station thirty minutes before.', 'When does the customer originally want to travel?', '[{"id":"a","text":"On Monday"},{"id":"b","text":"On Friday"},{"id":"c","text":"On Saturday"},{"id":"d","text":"On Tuesday"}]'::jsonb, 'd', 'The customer asks for a ticket for Tuesday, the 18th of November.', 'easy', array['listening-comprehension','step-mock']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
