insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-reading-18', 'reading', null, 'passage-sm2-5', null, null, 'According to the passage, how do date palms help the environment?', '[{"id":"a","text":"They reduce the amount of rain."},{"id":"b","text":"Their shade protects smaller crops from the sun."},{"id":"c","text":"They remove salt from the sea."},{"id":"d","text":"They attract tourists to the desert."}]'::jsonb, 'b', 'The passage says their shade protects smaller crops from the harsh sun (and their roots hold the soil).', 'medium', array['reading-comprehension','detail','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
