insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-reading-20', 'reading', null, 'passage-sm2-5', null, null, 'The passage is mainly about', '[{"id":"a","text":"how to grow dates at home"},{"id":"b","text":"the history of Bedouin travel"},{"id":"c","text":"the export of dates abroad"},{"id":"d","text":"the many uses and importance of the date palm"}]'::jsonb, 'd', 'Each paragraph describes a use or benefit of the date palm.', 'easy', array['reading-comprehension','main-idea','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-reading-21', 'reading', null, 'passage-sm2-6', null, null, 'In the passage, the word ''intruder'' is closest in meaning to', '[{"id":"a","text":"a helpful visitor"},{"id":"b","text":"something that enters where it does not belong"},{"id":"c","text":"a type of medicine"},{"id":"d","text":"a protective cell"}]'::jsonb, 'b', 'The immune system recognises the germ as foreign, something that enters the body where it does not belong.', 'medium', array['reading-comprehension','vocabulary','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-reading-22', 'reading', null, 'passage-sm2-6', null, null, 'Why do some vaccines need booster doses?', '[{"id":"a","text":"The germs change every year."},{"id":"b","text":"Babies cannot receive the first dose."},{"id":"c","text":"The body''s memory of the germ fades over time."},{"id":"d","text":"Antibodies turn into memory cells."}]'::jsonb, 'c', 'The passage says some vaccines need boosters ''because the memory fades over time''.', 'medium', array['reading-comprehension','detail','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-reading-23', 'reading', null, 'passage-sm2-6', null, null, 'In the passage, ''this'' in ''and this protects even those who cannot be vaccinated'' refers to', '[{"id":"a","text":"memory cells staying in the blood"},{"id":"b","text":"the vaccine containing a weakened germ"},{"id":"c","text":"the immune system making antibodies"},{"id":"d","text":"most people in a community being vaccinated"}]'::jsonb, 'd', 'The sentence says that when most people are vaccinated the disease struggles to spread, and this protects the others.', 'hard', array['reading-comprehension','pronoun-reference','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-reading-24', 'reading', null, 'passage-sm2-6', null, null, 'What can be inferred about smallpox from the passage?', '[{"id":"a","text":"Vaccination can remove a disease from the world."},{"id":"b","text":"It still kills millions today."},{"id":"c","text":"It was the first disease ever studied."},{"id":"d","text":"It never required booster doses."}]'::jsonb, 'a', 'Smallpox was ''completely wiped out in 1980 through worldwide vaccination'', so vaccination can eliminate a disease.', 'medium', array['reading-comprehension','inference','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-reading-25', 'reading', null, 'passage-sm2-7', null, null, 'In the passage, the word ''adopted'' is closest in meaning to', '[{"id":"a","text":"refused"},{"id":"b","text":"forgot"},{"id":"c","text":"started to use"},{"id":"d","text":"argued about"}]'::jsonb, 'c', 'Most countries gradually began using the time-zone system.', 'easy', array['reading-comprehension','vocabulary','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-reading-26', 'reading', null, 'passage-sm2-7', null, null, 'Why did railways make local sun time a problem?', '[{"id":"a","text":"Trains were too fast to time."},{"id":"b","text":"Clocks stopped working near the tracks."},{"id":"c","text":"Travellers did not trust the new trains."},{"id":"d","text":"Stations kept different times, which confused timetables."}]'::jsonb, 'd', 'Timetables became confusing because two stations kept different times.', 'easy', array['reading-comprehension','detail','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-reading-27', 'reading', null, 'passage-sm2-7', null, null, 'In the passage, ''This'' in ''This caused little trouble until railways appeared'' refers to', '[{"id":"a","text":"each town using its own local time"},{"id":"b","text":"the meeting held in Washington"},{"id":"c","text":"the invention of the clock"},{"id":"d","text":"the distance between cities"}]'::jsonb, 'a', 'The previous sentence says every town set its clocks by the sun, so times differed from place to place.', 'medium', array['reading-comprehension','pronoun-reference','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-reading-28', 'reading', null, 'passage-sm2-7', null, null, 'What is the author''s main purpose in the passage?', '[{"id":"a","text":"To compare Chinese and Saudi clocks"},{"id":"b","text":"To explain how and why standard time zones were created"},{"id":"c","text":"To criticise the railway companies"},{"id":"d","text":"To describe the history of Greenwich"}]'::jsonb, 'b', 'The passage moves from local sun time to the 1884 agreement and the system we use today.', 'medium', array['reading-comprehension','main-idea','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-reading-29', 'reading', null, 'passage-sm2-8', null, null, 'In the passage, the word ''scarce'' is closest in meaning to', '[{"id":"a","text":"dangerous"},{"id":"b","text":"plentiful"},{"id":"c","text":"tasty"},{"id":"d","text":"hard to find"}]'::jsonb, 'd', 'Camels use stored fat when food is scarce, meaning when it is not easy to find.', 'easy', array['reading-comprehension','vocabulary','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-reading-30', 'reading', null, 'passage-sm2-8', null, null, 'According to the passage, what does a camel''s hump store?', '[{"id":"a","text":"Fat"},{"id":"b","text":"Water"},{"id":"c","text":"Milk"},{"id":"d","text":"Sand"}]'::jsonb, 'a', 'The passage corrects the popular belief: the hump stores fat, not water.', 'easy', array['reading-comprehension','detail','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-reading-31', 'reading', null, 'passage-sm2-8', null, null, 'In the passage, ''it'' in ''it can then travel for days'' refers to', '[{"id":"a","text":"the water"},{"id":"b","text":"the camel"},{"id":"c","text":"the hump"},{"id":"d","text":"the desert"}]'::jsonb, 'b', '''A camel can drink... and it can then travel for days without drinking.''', 'easy', array['reading-comprehension','pronoun-reference','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-reading-32', 'reading', null, 'passage-sm2-8', null, null, 'Which statement best reflects the author''s view of camels?', '[{"id":"a","text":"They are no longer useful to anyone."},{"id":"b","text":"They are dangerous to travellers."},{"id":"c","text":"They are admirable animals that are still valued in the region."},{"id":"d","text":"They are difficult to breed."}]'::jsonb, 'c', 'The author praises their design and calls them a proud symbol that is still raced and bred.', 'medium', array['reading-comprehension','author-opinion','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-reading-33', 'reading', null, 'passage-sm2-9', null, null, 'In the passage, the word ''influential'' is closest in meaning to', '[{"id":"a","text":"having a strong effect on others"},{"id":"b","text":"hard to understand"},{"id":"c","text":"very old"},{"id":"d","text":"easy to carry"}]'::jsonb, 'a', 'Ranking the press among history''s most influential inventions means it had a great effect on the world.', 'medium', array['reading-comprehension','vocabulary','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-reading-34', 'reading', null, 'passage-sm2-9', null, null, 'Why were books so expensive before the printing press?', '[{"id":"a","text":"Paper was extremely rare."},{"id":"b","text":"They were copied by hand, which took months."},{"id":"c","text":"Kings taxed them heavily."},{"id":"d","text":"Few people could write."}]'::jsonb, 'b', 'Copying a single volume by hand could take a monk many months.', 'easy', array['reading-comprehension','detail','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-reading-35', 'reading', null, 'passage-sm2-9', null, null, 'In the passage, ''they'' in ''because they could no longer control what people read'' refers to', '[{"id":"a","text":"scientists"},{"id":"b","text":"families"},{"id":"c","text":"rulers"},{"id":"d","text":"monks"}]'::jsonb, 'c', '''Some rulers feared the new technology because they could no longer control...''', 'easy', array['reading-comprehension','pronoun-reference','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-reading-36', 'reading', null, 'passage-sm2-9', null, null, 'What can be inferred about the effect of cheaper books?', '[{"id":"a","text":"Fewer people learned to read."},{"id":"b","text":"Churches became richer."},{"id":"c","text":"Handwriting disappeared at once."},{"id":"d","text":"More people were able to learn and share ideas."}]'::jsonb, 'd', 'Prices fell, literacy rose, and ideas and discoveries travelled faster.', 'medium', array['reading-comprehension','inference','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-reading-37', 'reading', null, 'passage-sm2-10', null, null, 'In the passage, the word ''ideal'' is closest in meaning to', '[{"id":"a","text":"unusual"},{"id":"b","text":"most suitable"},{"id":"c","text":"distant"},{"id":"d","text":"dangerous"}]'::jsonb, 'b', 'Strong sunlight makes the peninsula the most suitable place for solar farms.', 'easy', array['reading-comprehension','vocabulary','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-reading-38', 'reading', null, 'passage-sm2-10', null, null, 'According to the passage, why are better batteries being developed?', '[{"id":"a","text":"Panels are too expensive."},{"id":"b","text":"Panels are too noisy."},{"id":"c","text":"Panels produce no electricity at night."},{"id":"d","text":"Panels need fuel to work."}]'::jsonb, 'c', 'Panels produce nothing at night, so extra daytime energy must be stored.', 'easy', array['reading-comprehension','detail','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-reading-39', 'reading', null, 'passage-sm2-10', null, null, 'In the passage, ''them'' in ''rather than replace them'' refers to', '[{"id":"a","text":"solar panels"},{"id":"b","text":"batteries"},{"id":"c","text":"engineers"},{"id":"d","text":"other energy sources"}]'::jsonb, 'd', 'Solar power will work alongside other sources rather than replace those sources.', 'medium', array['reading-comprehension','pronoun-reference','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-reading-40', 'reading', null, 'passage-sm2-10', null, null, 'What is the author''s view of the future of solar power?', '[{"id":"a","text":"It will grow but probably work alongside other sources."},{"id":"b","text":"It will end the need for all other energy."},{"id":"c","text":"It will remain limited to Saudi Arabia."},{"id":"d","text":"It is too expensive to continue."}]'::jsonb, 'a', 'The author is positive about solar power but says it will probably not replace other sources until storage improves.', 'hard', array['reading-comprehension','author-opinion','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-grammar-1', 'grammar', null, null, null, null, 'The weather today is ___ than it was yesterday.', '[{"id":"a","text":"warmer"},{"id":"b","text":"warm"},{"id":"c","text":"warmest"},{"id":"d","text":"more warm"}]'::jsonb, 'a', 'A short adjective takes -er before ''than'': warmer.', 'easy', array['comparatives','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-grammar-2', 'grammar', null, null, null, null, 'Neither of the answers ___ correct.', '[{"id":"a","text":"are"},{"id":"b","text":"is"},{"id":"c","text":"were"},{"id":"d","text":"be"}]'::jsonb, 'b', '''Neither of'' is treated as singular, so the verb is ''is''.', 'medium', array['subject-verb-agreement','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-grammar-3', 'grammar', null, null, null, null, 'We don''t have ___ information about the trip yet.', '[{"id":"a","text":"many"},{"id":"b","text":"a few"},{"id":"c","text":"much"},{"id":"d","text":"several"}]'::jsonb, 'c', '''Information'' is uncountable, so it takes ''much'' in a negative sentence.', 'easy', array['countable-uncountable','quantifiers','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
