insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-listening-9', 'listening', null, null, null, 'Sara: Have you finished your part of the presentation, Noura?
