insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-listening-11', 'listening', null, null, null, 'Announcement: Attention please, passengers travelling to Cairo on flight two-one-eight. Due to a technical check, your flight is now delayed by forty minutes. The original departure time was ten thirty, so the new departure time is ten past eleven. Please note that the gate has also changed from gate twelve to gate twenty. Passengers who would like a meal may collect a free voucher from the information desk near gate fifteen. We apologise for the inconvenience.', 'What is the new departure time?', '[{"id":"a","text":"11:10"},{"id":"b","text":"10:30"},{"id":"c","text":"11:00"},{"id":"d","text":"11:40"}]'::jsonb, 'a', 'The flight was due at 10:30 and is delayed by forty minutes, so it leaves at ten past eleven.', 'medium', array['listening-comprehension','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
