insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-writing-1', 'writingAnalysis', null, null, null, null, 'Which sentence is punctuated correctly?', '[{"id":"a","text":"When the bell rang, the students left the class."},{"id":"b","text":"When the bell rang the students, left the class."},{"id":"c","text":"When the bell rang the students left, the class."},{"id":"d","text":"When, the bell rang the students left the class."}]'::jsonb, 'a', 'A comma follows an introductory clause: ''When the bell rang,''.', 'easy', array['punctuation','commas','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-writing-2', 'writingAnalysis', null, null, null, null, 'Which sentence is correct?', '[{"id":"a","text":"The dog wagged it''s tail happily."},{"id":"b","text":"The dog wagged its tail happily."},{"id":"c","text":"The dog wagged its'' tail happily."},{"id":"d","text":"The dog wagged it tail happily."}]'::jsonb, 'b', '''Its'' is the possessive; ''it''s'' means ''it is'' or ''it has''.', 'medium', array['punctuation','apostrophes','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-writing-3', 'writingAnalysis', null, null, null, null, 'Which sentence uses capital letters correctly?', '[{"id":"a","text":"my cousin lives in jeddah and works at King Abdulaziz University."},{"id":"b","text":"My Cousin lives in Jeddah and works at king abdulaziz university."},{"id":"c","text":"My cousin lives in Jeddah and works at King Abdulaziz University."},{"id":"d","text":"My cousin lives in jeddah and works at King Abdulaziz university."}]'::jsonb, 'c', 'Capitalise the first word and proper nouns such as city and university names.', 'easy', array['capitalization','proper-nouns','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-writing-4', 'writingAnalysis', null, null, null, null, 'Identify the error: "The number of students in the library are increasing every year."', '[{"id":"a","text":"\"number\" should be \"numbers\""},{"id":"b","text":"\"in\" should be \"at\""},{"id":"c","text":"\"every\" should be \"each\""},{"id":"d","text":"\"are\" should be \"is\""}]'::jsonb, 'd', '''The number of'' takes a singular verb.', 'medium', array['error-identification','subject-verb-agreement','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-writing-5', 'writingAnalysis', null, null, null, null, 'Identify the error: "She doesn''t has any brothers or sisters."', '[{"id":"a","text":"\"doesn''t\" should be \"don''t\""},{"id":"b","text":"\"has\" should be \"have\""},{"id":"c","text":"\"any\" should be \"some\""},{"id":"d","text":"\"or\" should be \"and\""}]'::jsonb, 'b', 'After ''does/doesn''t'' the main verb is in the base form: have.', 'medium', array['error-identification','tenses','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-writing-6', 'writingAnalysis', null, null, null, null, 'Identify the error: "Between you and I, the film was disappointing."', '[{"id":"a","text":"\"Between\" should be \"Among\""},{"id":"b","text":"\"was\" should be \"is\""},{"id":"c","text":"\"I\" should be \"me\""},{"id":"d","text":"\"disappointing\" should be \"disappointed\""}]'::jsonb, 'c', 'After a preposition use the object pronoun: between you and me.', 'hard', array['error-identification','pronouns','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-writing-7', 'writingAnalysis', null, null, null, null, 'Identify the error: "He is one of the best player in the team."', '[{"id":"a","text":"\"one\" should be \"once\""},{"id":"b","text":"\"best\" should be \"better\""},{"id":"c","text":"\"in\" should be \"on\""},{"id":"d","text":"\"player\" should be \"players\""}]'::jsonb, 'd', '''One of the'' is followed by a plural noun.', 'medium', array['error-identification','plural-nouns','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-writing-8', 'writingAnalysis', null, null, null, null, 'Choose the correct word order:', '[{"id":"a","text":"Where did you buy that beautiful red jacket?"},{"id":"b","text":"Where you did buy that beautiful red jacket?"},{"id":"c","text":"Where did you buy that red beautiful jacket?"},{"id":"d","text":"Where did buy you that beautiful red jacket?"}]'::jsonb, 'a', 'Questions use auxiliary + subject, and adjectives follow the order opinion before colour.', 'medium', array['word-order','sentence-structure','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-writing-9', 'writingAnalysis', null, null, null, null, 'Choose the sentence that means the same as: "Despite the rain, we played outside."', '[{"id":"a","text":"We played outside because it was raining."},{"id":"b","text":"We did not play outside because of the rain."},{"id":"c","text":"We played outside although it was raining."},{"id":"d","text":"We played outside after the rain stopped."}]'::jsonb, 'c', '''Despite'' shows contrast, like ''although''.', 'easy', array['sentence-meaning','conjunctions','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-writing-10', 'writingAnalysis', null, null, null, null, 'Which sentence has correct parallel structure?', '[{"id":"a","text":"She likes swimming, to hike and reading."},{"id":"b","text":"She likes to swim, hiking and to read."},{"id":"c","text":"She likes swimming, hiking and to read."},{"id":"d","text":"She likes swimming, hiking and reading."}]'::jsonb, 'd', 'Items in a list must share the same form; here all three are -ing forms.', 'hard', array['parallel-structure','error-identification','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
